#include <bits/stdc++.h>
using namespace std;
int main(){
    int T;
    scanf("%d",&T);
    while(T--){
        int n;
        scanf("%d",&n);
        vector<int> p(n+1);
        for(int i=1;i<=n;i++) scanf("%d",&p[i]);
        vector<pair<int,int>> edges(n-1);
        vector<vector<pair<int,int>>> adj(n+1);
        for(int i=0;i<n-1;i++){
            int u,v; scanf("%d%d",&u,&v);
            edges[i]={u,v};
            adj[u].push_back({v,i});
            adj[v].push_back({u,i});
        }
        vector<int> par(n+1,0),order;
        vector<vector<int>> ch(n+1);
        vector<int> tin(n+1),tout(n+1);
        {
            vector<bool> vis(n+1,false);
            stack<pair<int,int>> st; st.push({1,0}); vis[1]=true;
            int tm=0;
            while(!st.empty()){
                auto [u,state]=st.top(); st.pop();
                if(state==0){
                    tin[u]=tm++;
                    order.push_back(u);
                    st.push({u,1});
                    for(auto [v,ei]:adj[u]) if(!vis[v]){vis[v]=true;par[v]=u;ch[u].push_back(v);st.push({v,0});}
                } else { tout[u]=tm++; }
            }
        }
        auto inSub=[&](int r,int x)->bool{return tin[r]<=tin[x]&&tout[x]<=tout[r];};
        vector<vector<int>> results;
        for(int iter=0;iter<2*n&&iter<4000;iter++){
            bool done=true;
            for(int i=1;i<=n;i++) if(p[i]!=i){done=false;break;}
            if(done) break;
            // For each edge, determine if swap is productive
            vector<pair<int,int>> scored;
            for(int i=0;i<n-1;i++){
                auto [u,v]=edges[i];
                int cv=v; if(par[v]!=u){cv=u;} // cv is the child endpoint
                bool pu_into = inSub(cv,p[u]==0?1:p[u]); // token at parent wants into subtree
                bool pv_out = !inSub(cv,p[cv]); // token at child wants out
                int pri=0;
                if(p[u]==u&&p[v]==v) pri=0;
                else if(pu_into&&pv_out) pri=3;
                else if(pu_into||pv_out) pri=2;
                else if(p[u]!=u||p[v]!=v) pri=1;
                if(pri>0) scored.push_back({pri,i});
            }
            sort(scored.begin(),scored.end(),[](auto&a,auto&b){return a.first>b.first;});
            vector<bool> used(n+1,false);
            vector<int> matching;
            for(auto [pri,ei]:scored){
                auto [u,v]=edges[ei];
                if(!used[u]&&!used[v]){used[u]=used[v]=true;matching.push_back(ei);swap(p[u],p[v]);}
            }
            if(matching.empty()) break;
            results.push_back(matching);
        }
        printf("%d\n",(int)results.size());
        for(auto&m:results){printf("%d",(int)m.size());for(int ei:m) printf(" %d",ei+1);printf("\n");}
    }
}
